insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('04cf3f51-b6e7-4d02-b9f5-741113f98832', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$intro tekst + structuurformule muscon$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context1.png$$,
   $$Muskus is een belangrijke geur die onderdeel uitmaakt van vrijwel alle parfums. Al ver voor het begin van onze jaartelling werd er gehandeld in muskus. Door het geringe aanbod was natuurlijke muskus altijd uiterst kostbaar. De belangrijkste geurstof in muskus is muscon, een stof met de molecuulformule C₁₆H₃₀O. De structuurformule van muscon is hiernaast schematisch weergegeven.

figuur: structuurformule van muscon — een macrocyclische ring met een ketongroep (C=O) en een CH₃-zijgroep aan het koolstofatoom naast de ring, met het label "muscon" eronder.$$, 'inline'),
  ('9bf71cde-2bca-4a1d-a2e6-b088967be6e4', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$figuur 1 — synthese muskxyleen (stap 1 en stap 2) + rendementen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context2.png$$,
   $$De productie van synthetische muscon is nooit van de grond gekomen. Het rendement van de voorgestelde bereidingswijzen was steeds erg laag, mede vanwege het grote aantal tussenstappen. Ook kwamen goedkopere vervangers voor muscon beschikbaar: de nitromusks. De nitromusks zijn eenvoudig te bereiden uit goedkope grondstoffen. Zo kan muskxyleen (MX) worden bereid in slechts twee stappen die in figuur 1 zijn weergegeven.

figuur 1: reactieschema in twee stappen. Stap 1: 1,3-dimethylbenzeen + methylpropeen (CH₂=C(CH₃)₂) → 1-tert-butyl-3,5-dimethylbenzeen ((CH₃)₃C-C₆H₃(CH₃)₂). Stap 2: dat product + 3 HNO₃ → muskxyleen (de trinitroverbinding met drie NO₂-groepen op de ring) + 3 H₂O.

In stap 1 uit figuur 1 laat men 1,3-dimethylbenzeen reageren met methylpropeen. Deze omzetting heeft een rendement van 75%. Vervolgens laat men de ontstane stof na zuivering reageren met geconcentreerd salpeterzuur tot MX en water. Deze tweede stap heeft een rendement van 88%.$$, 'inline'),
  ('4ed23529-48b1-4aff-8488-816ee00693c7', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$MX hecht aan katoen via –NO2-groepen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context3.png$$,
   $$MX hecht goed aan textiel, waardoor de geur lang blijft hangen. MX is hydrofoob. Daarom is het opmerkelijk dat MX goed hecht aan bijvoorbeeld katoen. Katoen bestaat vooral uit cellulose. Van katoen is bekend dat het goed water kan binden. Het blijkt dat de binding aan katoen vooral door de in MX aanwezige –NO₂ groepen plaatsvindt. Met behulp van Lewisstructuren kan worden verklaard waarom MX goed hecht aan katoen. Op de uitwerkbijlage die bij dit examen hoort, zijn een nitrogroep van MX en een gedeelte van een molecuul cellulose schematisch en onvolledig weergegeven.$$, 'inline'),
  ('864de65b-d232-4fa5-99e4-cb670f110202', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$hypothese huidpassage MX + verdelingsevenwicht MX(aq)⇌MX(vet)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context4.png$$,
   $$Het bleek dat nitromusks kunnen worden aangetoond in oppervlaktewater en in het vetweefsel van vissen en mensen. Omdat nitromusks ervan worden verdacht kankerverwekkend te zijn, is het gebruik sterk teruggedrongen. Uit kwalitatief onderzoek aan vissen bleek dat MX wordt opgenomen uit het water via de huid, waarna het zich in het onderhuids vetweefsel ophoopt. Onderzoekers stelden de hypothese op dat MX de huid in beide richtingen kan passeren. Het verdelingsevenwicht van MX in het water en in het vetweefsel kan worden voorgesteld als:

MX (aq) ⇌ MX (vet)$$, 'inline'),
  ('9e6223cb-39b8-4a0d-bcd9-c6b21a706625', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$modelproeven K ≈ 4·10³, blootstelling 22,5 ng/L, [MX(vet)] 105 µg/L$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context5.png$$,
   $$Op basis van modelproeven leidden de onderzoekers af dat de waarde van de evenwichtsconstante K van bovengenoemd evenwicht ongeveer 4·10³ moest bedragen. Om deze waarde te toetsen, werd een kwantitatief onderzoek aan vissen uitgevoerd. In een aquarium werden vissen blootgesteld aan een constant gehalte MX van 22,5 nanogram MX per liter. Men stelde vast dat [MX (vet)] in het vetweefsel van de vissen aanvankelijk snel steeg, maar zich na enige tijd stabiliseerde bij 105 microgram MX per liter vet.$$, 'inline'),
  ('49a7731e-00ad-4318-8b14-9e20eef6acd8', '892ed6f6-3084-4bdf-8397-80fcc8d49c9a', $$uitwerkbijlage vraag 3 — Lewisstructuur nitrogroep MX en OH-groep cellulose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-nitromusks-context6.png$$,
   $$Uitwerkbijlage bij vraag 3: een nitrogroep van MX (een golflijn voor de rest van het molecuul, verbonden met een N-atoom dat op zijn beurt verbonden is met twee O-atomen; ladingen en bindingen zijn nog niet ingetekend) en een gedeelte van een molecuul cellulose (een pyranosering met een CH₂OH-zijgroep, weergegeven als H–O–CH₂–, en een OH-groep aan de ring; golflijnen geven de rest van de cellulosestructuur aan). De kandidaat moet de Lewisstructuur van de nitrogroep en van de bovenste OH-groep completeren, met formele en partiële ladingen.$$, 'uitwerkbijlage'),
  ('9c671ce4-c912-43c6-b537-fb54596372eb', 'b2608f9f-cc59-4c63-9a45-ae3fc7b68850', $$intro snijbrander + ethyn(C2H2)/ethaan(C2H6) + foto$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-heet-context1.png$$,
   $$Voor het snijden van ijzeren voorwerpen zoals spoorrails worden snijbranders gebruikt. In een snijbrander wordt vrijwel altijd acetyleen (ethyn, C₂H₂) gebruikt in combinatie met zuivere zuurstof. Met deze ethyn-zuurstofvlam kan een vlamtemperatuur van ruim boven het smeltpunt van ijzer worden bereikt. Andere koolwaterstoffen zoals ethaan (C₂H₆) zijn onbruikbaar voor het snijden van ijzer door een te lage vlamtemperatuur.
De temperatuur die een vlam maximaal kan bereiken, hangt vooral af van twee factoren:
− de reactiewarmte van de verbranding van de brandstof;
− welke verbrandingsproducten ontstaan en in welke hoeveelheden.
Als aangenomen wordt dat ethyn volledig verbrandt, ontstaan koolstofdioxide en waterdamp. Wanneer verlies van energie naar de omgeving wordt verwaarloosd, wordt de vrijkomende energie uitsluitend gebruikt om koolstofdioxide en waterdamp te verwarmen. Met behulp van de reactiewarmte van de verbranding (de verbrandingswarmte) van ethyn en de soortelijke warmtes van koolstofdioxide en water kan de temperatuurstijging van het gasmengsel berekend worden. Bij volledige verbranding van ethyn zou de maximale temperatuur van de vlam boven 7·10³ K liggen.
De soortelijke warmte van een stof kan worden gedefinieerd als het aantal joule dat nodig is om 1 g stof 1 K in temperatuur te laten stijgen.

foto: een snijbrander die met een vonkenregen een spoorrail doorsnijdt.$$, 'inline'),
  ('845ad4d9-da65-4f09-9bc2-1d294425682e', 'b2608f9f-cc59-4c63-9a45-ae3fc7b68850', $$diagram 1 — % waterdamp ontleed vs temperatuur + evenwicht 2000-3500K$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-heet-context2.png$$,
   $$Als waterdamp wordt verhit, blijkt water namelijk te ontleden in waterstof en zuurstof. In diagram 1 is weergegeven welk percentage van de watermoleculen is ontleed afhankelijk van de temperatuur.

diagram 1: grafiek van het percentage water ontleed (%, 0-80) tegen de temperatuur (K, 1500-3500). De curve blijft vrijwel vlak (bijna 0%) tot ongeveer 2000 K en stijgt daarna geleidelijk versneld tot ongeveer 62% bij 3500 K.

Tussen 2000 K en 3500 K is de ontleding van waterdamp een evenwicht.$$, 'inline'),
  ('c47475a2-25a6-4178-b449-0cea3b0fe99b', 'b2608f9f-cc59-4c63-9a45-ae3fc7b68850', $$verbrandingsproducten ethyn+zuurstof: CO en H2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-heet-context3.png$$,
   $$Uit metingen blijkt dat bij de reactie van ethyn met zuurstof vooral koolstofmonoöxide en waterstof worden gevormd.$$, 'inline'),
  ('c45523b2-3cdd-4b53-a4cf-74d0578bfd4c', 'b2608f9f-cc59-4c63-9a45-ae3fc7b68850', $$vergelijking ethyn- en ethaan-zuurstofvlam (mol gas, reactiewarmte)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-heet-context4.png$$,
   $$Op basis van de aanname dat de verbrandingsproducten van de ethyn-zuurstofvlam CO en H₂ zijn, kan worden berekend dat dan een temperatuurstijging van ruim 3·10³ K bereikt wordt.
De temperatuurstijging die kan worden bereikt met een ethaan-zuurstofvlam, waarbij ook CO en H₂ ontstaan, is lager dan van de ethyn-zuurstofvlam.
Dit wordt onder andere veroorzaakt doordat bij de ethaan-zuurstofvlam meer mol gas moet worden verwarmd. Ook is de reactiewarmte lager.
Op de uitwerkbijlage bij dit examen zijn twee energiediagrammen weergegeven. Hierin zijn de energieniveaus van de niet-ontleedbare stoffen en de reactieproducten al aangegeven.$$, 'inline'),
  ('7a624ce7-3dbb-4cd8-9e7c-df2a07dc43d3', 'b2608f9f-cc59-4c63-9a45-ae3fc7b68850', $$uitwerkbijlage vraag 9 — energiediagrammen ethyn- en ethaanverbranding$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-heet-context5.png$$,
   $$Uitwerkbijlage bij vraag 9: twee energiediagrammen naast elkaar, voor de ethaan-zuurstofvlam (links) en de ethyn-zuurstofvlam (rechts), elk met een verticale as "energie". In beide diagrammen is alleen het energieniveau van de reactieproducten (…CO + …H₂) al ingetekend; het energieniveau van de beginstoffen ontbreekt nog en moet door de kandidaat worden ingetekend, samen met de molecuulformules en coëfficiënten van de reacties.$$, 'uitwerkbijlage'),
  ('036be292-a385-475d-a466-6e3cea05722e', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$doelstelling 3,0% biogas, reactiewarmte -2,0·10⁷ J/m³$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context1.png$$,
   $$Methaan uit aardgas levert in Nederland per jaar ongeveer 1,5·10¹⁸ J aan energie. In 2007 werd in het rapport "Vol gas vooruit!" het doel gesteld dat op korte termijn 3,0% van deze energie wordt geleverd door biogas. Biogas ontstaat wanneer biomassa door een mengsel van bacteriën wordt afgebroken onder zuurstofarme omstandigheden. De hoofdbestanddelen van biogas zijn koolstofdioxide en methaan. De reactiewarmte bij de verbranding van biogas bedraagt gemiddeld –2,0·10⁷ J m⁻³. Deze energiewaarde kan vooral worden toegeschreven aan het aanwezige methaan.$$, 'inline'),
  ('11bc4d8a-430a-459f-847f-a915b546af7f', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$reactievergelijking vorming biogas CcHhOoNnSs + x/y-formules$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context2.png$$,
   $$Hieronder is een reactievergelijking voor het totale proces van de vorming van biogas uit biomassa weergegeven. Voor biomassa wordt de verhoudingsformule CcHhOoNnSs gebruikt.

CcHhOoNnSs + y H₂O → x CH₄ + n NH₃ + s H₂S + (c-x) CO₂
x = 0,125(4c + h - 2o - 3n + 2s)
y = 0,250 (4c - h - 2o + 3n + 2s)$$, 'inline'),
  ('504c78a8-2210-433e-86e1-94e743a50f0b', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$verhoudingsformule biomassafractie C38H60O26N3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context3.png$$,
   $$Een bepaalde fractie biomassa kan worden voorgesteld met de volgende verhoudingsformule: C₃₈H₆₀O₂₆N₃.$$, 'inline'),
  ('8292adc7-173a-4b90-942b-1cf2ca6102b9', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$stap 1 hydrolyse — producten suikers, aminozuren, vetzuren, glycerol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context4.png$$,
   $$Biomassa bestaat voornamelijk uit koolhydraten, vetten en eiwitten. De vorming van biogas uit biomassa gebeurt in vier stappen. Deze stappen verlopen tegelijkertijd.
Stap 1: hydrolyse. Tijdens deze stap worden de koolhydraten, eiwitten en vetten met behulp van enzymen buiten de bacteriecellen afgebroken tot suikers, aminozuren, vetzuren en glycerol. De producten van de hydrolyse worden door bacteriën opgenomen.$$, 'inline'),
  ('072626d6-1371-4298-92fb-47ea51fef14c', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$stap 2 verzuring — zuren/alcoholen, H2/CO2, bijproducten NH3/H2S$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context5.png$$,
   $$Stap 2: verzuring. De in stap 1 gevormde stoffen worden in de bacteriën omgezet tot zuren en alcoholen. Hierbij ontstaan tevens waterstof en koolstofdioxide. Als bijproducten worden ammoniak en waterstofsulfide (H₂S) gevormd.$$, 'inline'),
  ('d2911ae3-245f-4268-90f8-783922ddccbd', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$stap 3 azijnzuurvorming — even/oneven aantal C-atomen en CO2-vorming$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context6.png$$,
   $$Stap 3: azijnzuurvorming. Zogenoemde azijnzuurvormende bacteriën zetten de in stap 2 gevormde zuren en alcoholen met water om tot ethaanzuur en waterstof. Als in een zuur of alcohol een oneven aantal C atomen aanwezig is, ontstaat hierbij tevens CO₂. Bij een even aantal C atomen ontstaat geen CO₂. De reacties in stap 3 kunnen worden voorgesteld als evenwichtsreacties.$$, 'inline'),
  ('6fe3ba62-62d1-4054-bd66-bfa0510d3ff3', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$stap 4 methaanvorming + sulfaat-afbrekende bacteriën + halfreactie SO4²⁻$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context7.png$$,
   $$In stap 4 wordt door methaanvormende bacteriën ten slotte methaan en CO₂ gevormd. Hierbij verbruiken ze het in stap 2 gevormde waterstof.
In sommige bronnen van biomassa, zoals havenslib, zijn veel sulfaationen aanwezig. De aanwezigheid van sulfaat-afbrekende bacteriën in een reactor kan dan de methaanproductie verminderen. Deze bacteriën verbruiken namelijk het aanwezige waterstof om sulfaationen om te zetten tot H₂S. De vergelijking van de halfreactie van het sulfaation is hieronder weergegeven.

SO₄²⁻ + 10 H⁺ + 8 e⁻ → H₂S + 4 H₂O$$, 'inline'),
  ('b0184090-0464-4867-b22d-0165dfd05163', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$H2S/HS⁻ giftigheid + diagram 1 — methaanvorming vs Na2S bij 3 pH's$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context8.png$$,
   $$Het gevormde H₂S en het tevens aanwezige HS⁻ zijn bij een hoge concentratie giftig voor de methaanvormende bacteriën.
Om het remmende effect van H₂S en HS⁻ op de methaanproductie te onderzoeken werd in een laboratoriumopstelling de methaanproductie van methaanvormende bacteriën bepaald na toevoeging van verschillende hoeveelheden Na₂S. Dit experiment werd uitgevoerd bij drie pH-waarden, die met behulp van buffers werden ingesteld. De overige omstandigheden werden constant gehouden. In diagram 1 is het resultaat van de metingen weergegeven.

diagram 1: grafiek van de activiteit methaanvorming (%, 0-100) tegen de hoeveelheid toegevoegd Na₂S (g L⁻¹, 0-1,400), voor drie pH-waarden: pH = 6,35 (vierkantjes, steilste daling: 50% bij ca. 0,09 g/L, 0% bij ca. 0,18 g/L), pH = 7,10 (rondjes: 50% bij 0,20 g/L, 0% bij ca. 0,38 g/L) en pH = 7,95 (sterretjes, veel geleidelijkere daling: 50% bij 0,90 g/L, nog ca. 22% bij 1,400 g/L).$$, 'inline'),
  ('5bf01c48-8524-45a4-b6d6-707586a54407', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$evenwicht S²⁻ → H2S/HS⁻ bij gebruikte pH-waarden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context9.png$$,
   $$Bij de gebruikte pH-waarden worden de opgeloste S²⁻ ionen volledig omgezet tot H₂S en HS⁻.
In de oplossing stelt zich het volgende evenwicht in:

H₂S + H₂O ⇌ H₂O⁺ + HS⁻$$, 'inline'),
  ('17d719fc-7014-482a-bf77-a08dedff1bfd', 'e545c368-398b-49d8-94bc-ab7f97d86102', $$meetgegevens 50%-afname bij pH 7,10 (0,20 g Na2S/L) en pH 7,95 (0,90 g Na2S/L)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-context10.png$$,
   $$Bij pH = 7,10 is een afname van 50% van de methaanvorming gemeten na het toevoegen van 0,20 g Na₂S per liter. Berekend kan worden dat dan de concentratie H₂S 0,041 g L⁻¹ bedraagt.
Bij pH = 7,95 is dezelfde afname van de methaanvorming gemeten na het toevoegen van 0,90 g Na₂S per liter. Hoewel in deze proef meer Na₂S is toegevoegd, is er toch ongeveer evenveel H₂S aanwezig als in de genoemde proef bij pH = 7,10.$$, 'inline'),
  ('3f3158df-d3de-4ceb-9867-acfb98ae6417', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$MGS/EGS-proces intro + reactie R1 (Si+HCl→SiHCl3+H2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context1.png$$,
   $$Chips voor elektronica worden gemaakt van dunne ronde schijven zeer zuiver silicium, wafers genoemd. Het benodigde silicium wordt gewonnen uit de steensoort kwartsiet. Hieruit kan silicium worden verkregen met een zuiverheid van ruim 98%. Dit wordt metallurgical-grade silicium (MGS) genoemd. MGS dient als grondstof voor de bereiding van electronical grade silicium (EGS), dat een zuiverheid heeft van 99,999999999%. Het productieproces van EGS uit MGS staat in de uitwerkbijlage die bij dit examen hoort in een onvolledig blokschema weergegeven.
In reactor R1 reageert MGS met HCl. Hierbij wordt het silicium uit MGS omgezet tot SiHCl₃ en waterstof. Het HCl reageert hierbij volledig.$$, 'inline'),
  ('495f968e-be9b-4611-aec6-03b4bd589baa', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$dipool-dipoolbinding Si-Cl + tabel 1 — kookpunten reactieproducten$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context2.png$$,
   $$Behalve SiHCl₃ en waterstof ontstaan nog allerlei andere reactieproducten in R1. De voornaamste reactieproducten en hun kookpunten staan vermeld in tabel 1. De siliciumverbindingen die in R1 worden gevormd, hebben verschillende kookpunten. Dit kan worden verklaard aan de hand van de sterkte van de bindingen tussen de moleculen. Tussen de moleculen van een aantal van de in tabel 1 genoemde stoffen is een dipool-dipoolbinding aanwezig. Deze binding wordt veroorzaakt door de aanwezigheid van één of meer polaire Si–Cl atoombindingen.

tabel 1 — kookpunten:
Si: 3538 K; reactieproduct SiH₃Cl: 243 K, SiH₂Cl₂: 281 K, SiHCl₃: 306 K, SiCl₄: 331 K.
Al: 2792 K; reactieproduct AlCl₃: 466 K.
Fe: 3134 K; reactieproduct FeCl₂: 1296 K, FeCl₃: 589 K.$$, 'inline'),
  ('d0d3134f-b19e-47e7-8eb3-d74f14380486', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$scheidingsproces S1-S4 en R2 (rendement 30%)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context3.png$$,
   $$De in R1 ontstane stoffen AlCl₃, FeCl₂ en FeCl₃ worden in R1 al direct afgevoerd als afval. Het mengsel van gassen en vloeistoffen dat overblijft, wordt in S1 gedestilleerd bij 308 K. In alle destillatiestappen in dit proces komt (komen) de stof(fen) met het laagste kookpunt boven uit de destillatiekolom.
In S2 wordt het uit S1 afkomstige mengsel gedestilleerd bij 303 K, waardoor zeer zuiver SiHCl₃ wordt verkregen.
In reactor R2 wordt het SiHCl₃ met waterstof weer omgezet tot gasvormig silicium en HCl. In R2 vindt dus de omgekeerde reactie plaats van R1. Het silicium rijpt hierbij op een kristallisatiekern van zeer zuiver silicium. Zo ontstaat een staaf vast silicium (EGS).
SiHCl₃ reageert in R2 echter ook met het in R2 gevormde HCl, waarbij SiCl₄ en H₂ ontstaan. In R2 reageert niet al het SiHCl₃ met H₂, waardoor slechts een rendement van 30% wordt behaald.
In S3 wordt het gasmengsel afkomstig uit S2 en R2 gebracht. In S3 worden waterstof en HCl gescheiden van de siliciumverbindingen. De siliciumverbindingen worden weer teruggevoerd in het proces.
In S4 worden waterstof en HCl van elkaar gescheiden, waarna ze elk worden teruggevoerd in het proces.
Het SiCl₄ afkomstig uit S1 wordt niet teruggevoerd in het proces.
In het proces wordt geen H₂ van buiten aangevoerd.$$, 'inline'),
  ('c417dda1-7f81-4420-ba5a-81767857f25f', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$boor als verontreiniging — invloed op roosteropbouw$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context4.png$$,
   $$Het silicium (EGS) dat volgens dit proces ontstaan is, is nog niet bruikbaar als materiaal voor computerchips. De kristalstructuur bevat nog te veel onregelmatigheden.
Een van de meest schadelijke verontreinigingen in silicium voor chips is het element boor. De aanwezigheid van deeltjes boor heeft invloed op de roosteropbouw en de geleidbaarheid van het silicium.$$, 'inline'),
  ('a90ccf83-8d12-47e8-a9e6-0f63b11184f4', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$Czochralski-proces + evenwichtsconstante K=Cs/Cl$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context5.png$$,
   $$Om het gevormde EGS nog verder te zuiveren wordt het omgesmolten via het Czochralski-proces.
Men laat een kristal zeer zuiver silicium, de zogeheten kiem, neer op een hoeveelheid gesmolten EGS. Aan het oppervlak van de kiem stolt het silicium. Door het geheel langzaam omhoog te trekken, ontstaan uiteindelijk lange staven zeer zuiver silicium. Dit silicium is geschikt voor toepassing in computerchips.

figuur: schematische weergave van het Czochralski-proces — een cilindervormig vat met gesmolten silicium waaruit aan een dunne staaf (de kiem) een vaste siliciumstaaf omhoog wordt getrokken (pijl omhoog).

Het stollingsproces zorgt voor extra zuivering van het silicium. De extra zuivering is te verklaren door de verschillende oplosbaarheden van een onzuiverheid in vast en vloeibaar silicium. Aan het grensvlak tussen vast en vloeibaar silicium stelt zich namelijk een verdelingsevenwicht in.
De waarde van de evenwichtsconstante K voor dit verdelingsevenwicht kan worden berekend volgens:

K = Cs / Cl

Hierin is Cs de concentratie in mol L⁻¹ van de onzuiverheid in vast silicium en Cl de concentratie van de onzuiverheid in vloeibaar silicium.$$, 'inline'),
  ('e92bcbf4-3855-4490-92f1-41daacb4dc8e', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$tabel 2 — K-waarden onzuiverheden + interpretatie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context6.png$$,
   $$Voor enkele onzuiverheden in silicium zijn de waarden van K vermeld in tabel 2.

tabel 2 — K-waarden: Al: 2·10⁻³; As: 3·10⁻¹; B: 8·10⁻¹; C: 7·10⁻²; Cu: 4·10⁻⁶; Fe: 8·10⁻⁶; Sb: 2·10⁻².

Uit tabel 2 is af te leiden hoe groot het gedeelte van een aanwezige verontreiniging is, dat in het vaste silicium terechtkomt.$$, 'inline'),
  ('00dfd2c8-1416-48a9-b89d-225835f9e25f', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$boorconcentratie <1 ppb, stijgende vervuiling vloeibaar silicium$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context7.png$$,
   $$Het silicium dat in het Czochralskiproces wordt ingevoerd, bevat minder dan 1 deeltjes-ppb boor. Eén deeltjes-ppb is één deeltje onzuiverheid per 10⁹ deeltjes. Een nadeel van het Czochralskiproces is dat voor een goede kwaliteit van de siliciumstaven, niet al het vloeibare silicium kan worden gekristalliseerd. Dit komt doordat gedurende het proces, de concentratie van de vervuiling in het vloeibare silicium stijgt.$$, 'inline'),
  ('7ac22f3e-fde4-43fa-996e-233c1052c8ac', 'c1022293-b4f7-4a14-8ba3-e1c8b3a6a04d', $$uitwerkbijlage vraag 20 — onvolledig blokschema EGS-productieproces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-99999999999-procent-zuiver-silicium-context8.png$$,
   $$Uitwerkbijlage bij vraag 20: onvolledig blokschema van het EGS-productieproces. Te zien zijn: R1 (instroom Si (MGS) en HCl, uitstroom afval) met een pijl naar S1; S1 met een pijl gelabeld "4" naar beneden en een pijl naar S2; S2 met een pijl naar boven (naar S3) en een pijl naar beneden (naar R2); R2 met een pijl naar boven gelabeld "3,4,5,6" (naar S3) en een pijl naar beneden met de uitstroom "Si (EGS)"; S3 met een pijl naar S4 en een ongelabelde pijl naar beneden die het schema verlaat; S4 met een ongelabelde pijl naar boven die het schema verlaat. De kandidaat moet de ontbrekende pijlen (met name de retourstromen die het schema bij S3 en S4 verlaten, terug naar R1 en R2) intekenen en alle pijlen voorzien van de juiste stofstroomnummers (1 SiH₃Cl, 2 SiH₂Cl₂, 3 SiHCl₃, 4 SiCl₄, 5 H₂, 6 HCl).$$, 'uitwerkbijlage');

