  ('6528f022-c300-497c-8581-e8944cf1cf72', 'e545c368-398b-49d8-94bc-ab7f97d86102', 15,
   '[{"domain": "Reacties", "subdomain": "Chemisch evenwicht"}]'::jsonb,
   '["diagram interpreteren", "waterstofsulfide", "pH", "remming", "methaanvorming"]'::jsonb,
   $$Bepalen welk deeltje (H₂S of HS⁻) de methaanvorming het sterkst remt op basis van diagram 1 bij verschillende pH-waarden.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-i-biogasfabricage-uit-afval-vraag15.png$$, $$Leg met behulp van diagram 1 uit welk deeltje de methaanvorming het sterkst remt: H₂S of HS⁻.$$, array['b0184090-0464-4867-b22d-0165dfd05163', '5bf01c48-8524-45a4-b6d6-707586a54407']::uuid[]),
  ('667fb223-5e97-432d-a56d-9e7d356fac2a', 'e545c368-398b-49d8-94bc-ab7f97d86102', 16,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
